-- Runtime query contract for the removable cpf-reference Batch pack.
SELECT JOB_EXECUTION_KEY, REQUIREMENT_ID, BUSINESS_KEY, DATA_SCOPE, JOB_NAME,
       JOB_INSTANCE_KEY, IDEMPOTENCY_KEY, STATE, FENCING_TOKEN, ATTEMPT_COUNT,
       PAYLOAD_JSON, RESULT_JSON, CREATED_AT, UPDATED_AT, COMPLETED_AT
  FROM CPF_REF_BAT_JOB_EXECUTION
 WHERE REQUIREMENT_ID = :requirementId
   AND IDEMPOTENCY_KEY = :idempotencyKey;

SELECT JOB_EXECUTION_KEY, STEP_NAME, PARTITION_KEY, CHECKPOINT_VERSION,
       STATE, CHECKPOINT_JSON, UPDATED_AT
  FROM CPF_REF_BAT_CHECKPOINT
 WHERE JOB_EXECUTION_KEY = :jobExecutionKey
 ORDER BY STEP_NAME, PARTITION_KEY;

SELECT TARGET_RESULT_ID, JOB_EXECUTION_KEY, TARGET_KEY, STATE, ATTEMPT_COUNT,
       RESULT_JSON, ERROR_CODE, ERROR_MESSAGE, UPDATED_AT
  FROM CPF_REF_BAT_TARGET_RESULT
 WHERE JOB_EXECUTION_KEY = :jobExecutionKey
 ORDER BY TARGET_KEY;
